--------------------------------------------------------
--  DDL for View GELEN_ÝLAC
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "GELEN_ÝLAC" ("ILAC_ADI", "FIYAT", "ILACFIRMA") AS 
  SELECT
    i.adi        AS ilac_adi,
    i.fiyat,
    f.firmaisim   AS ilacfirma
FROM ilac i
INNER JOIN ilacfirma f
    ON i.firmaid = f.firmaid
;
--------------------------------------------------------
--  DDL for View SATÝLANÝLAC
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SATÝLANÝLAC" ("RECETENO", "SATISTARIH", "ADI", "FIYAT", "KDV", "KDVLI_FIYAT") AS 
  SELECT 
    s.receteno,
    s.satistarih,
    i.adi,
    i.fiyat,
    k.kdv,
    i.fiyat * k.kdv AS kdvli_fiyat
FROM satilanilac s
INNER JOIN receteilac ri ON s.receteno = ri.receteno
INNER JOIN ilac i ON ri.ilacid = i.ilacid
INNER JOIN kdv k ON i.kdvid = k.kdvid
ORDER BY s.satistarih DESC
;
--------------------------------------------------------
--  DDL for View STOKMÝKTARI
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "STOKMÝKTARI" ("ILACID", "ILAC", "STOKADET") AS 
  SELECT
    i.ilacid,
    i.adi        AS ilac,
    d.stokadet
FROM ilac i
INNER JOIN ilacdepo d
    ON i.ilacid = d.id
;
